cat > /tmp/parse_binlog.cs << 'EOF'
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var build = BinaryLog.ReadBuild(args[0]);
var errors = build.FindChildrenRecursive<Error>();
var warnings = build.FindChildrenRecursive<Warning>();

Console.WriteLine("=== BUILD ERRORS ===");
foreach (var e in errors)
{
    var parent = e.Parent;
    string project = "";
    while (parent != null)
    {
        if (parent is Project p) { project = p.Name; break; }
        parent = parent.Parent;
    }
    Console.WriteLine($"[{project}] {e.File}({e.LineNumber},{e.ColumnNumber}): error {e.Code}: {e.Text}");
}

Console.WriteLine("\n=== BUILD WARNINGS (non-info) ===");
foreach (var w in warnings.Where(w => w.Code != null && (w.Code.StartsWith("CS") || w.Code.StartsWith("NU") || w.Code.StartsWith("MSB"))))
{
    var parent = w.Parent;
    string project = "";
    while (parent != null)
    {
        if (parent is Project p) { project = p.Name; break; }
        parent = parent.Parent;
    }
    Console.WriteLine($"[{project}] {w.File}({w.LineNumber},{w.ColumnNumber}): warning {w.Code}: {w.Text}");
}

// Also check for failed targets
Console.WriteLine("\n=== FAILED PROJECTS ===");
var projects = build.FindChildrenRecursive<Project>();
foreach (var p in projects)
{
    if (!p.Succeeded)
        Console.WriteLine($"FAILED: {p.Name} ({p.ProjectFile})");
}
EOF

