using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var build = BinaryLog.ReadBuild(args[0]);

// Get all project nodes and their success status
Console.WriteLine("=== PROJECT BUILD RESULTS ===");
var projects = build.FindChildrenRecursive<Project>();
foreach (var p in projects)
{
    var errs = p.FindChildrenRecursive<Error>();
    Console.WriteLine($"{p.Name} - Errors: {errs.Count()}");
}

// Get source content embedded in binlog
Console.WriteLine("\n=== SOURCE FILES FROM BINLOG ===");
var sourceFiles = build.FindChildrenRecursive<SourceFile>();
foreach (var sf in sourceFiles)
{
    Console.WriteLine($"File: {sf.Name} ({sf.GetType().Name})");
}

// Also look at the actual source from SourceFilesArchive
Console.WriteLine("\n=== CHECKING EMBEDDED SOURCES ===");
var archive = build.SourceFilesArchive;
if (archive != null)
{
    foreach (var entry in archive.Children)
    {
        if (entry.ToString().Contains("UserService") || entry.ToString().Contains("Models") || entry.ToString().Contains("Program"))
            Console.WriteLine($"Archive entry: {entry}");
    }
}
EOF
