cd /tmp && cat > parse_binlog.cs << 'EOF'
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.IO;
using System.Linq;

var build = BinaryLog.ReadBuild(args[0]);

// Check the SourceFiles embedded in binlog
Console.WriteLine("=== EMBEDDED SOURCE ARCHIVE ===");
var archive = build.SourceFilesArchive;
if (archive != null)
    Console.WriteLine($"Archive size: {archive.Length} bytes");
else
    Console.WriteLine("No archive found");

// Look for the actual compilation items to understand the source
Console.WriteLine("\n=== CSC TASK ITEMS ===");
var tasks = build.FindChildrenRecursive<Task>().Where(t => t.Name == "Csc");
foreach (var task in tasks)
{
    var parent = task.Parent;
    string project = "";
    var p2 = task.Parent;
    while (p2 != null) { if (p2 is Project pr) { project = pr.Name; break; } p2 = p2.Parent; }
    Console.WriteLine($"\n  Csc in {project}:");
    // Print command line params
    var parameters = task.FindChildrenRecursive<Parameter>();
    foreach (var param in parameters.Where(p => p.Name == "Sources" || p.Name == "References"))
    {
        Console.WriteLine($"    {param.Name}:");
        foreach (var item in param.Children.Take(20))
            Console.WriteLine($"      {item}");
    }
}

// Try reading the actual file content from the binlog's SourceFiles
Console.WriteLine("\n=== TRYING TO READ EMBEDDED FILES ===");
using var stream = new FileStream(args[0], FileMode.Open, FileAccess.Read);
var reader = new BinLogReader();
var records = reader.ReadRecords(stream).ToList();
Console.WriteLine($"Total records: {records.Count}");
var embeddedTexts = records.Where(r => r.Args?.GetType().Name?.Contains("Embedded") == true).ToList();
Console.WriteLine($"Embedded text records: {embeddedTexts.Count}");
EOF
