arguments.command:
cd /tmp && cat > parse_binlog.cs << 'EOF'
using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;

var build = BinaryLog.ReadBuild(args[0]);

// Check if Api's Csc task ran at all
var tasks = build.FindChildrenRecursive<Task>().Where(t => t.Name == "Csc").ToList();
Console.WriteLine($"Total Csc tasks: {tasks.Count}");
foreach (var t in tasks)
{
    var p = t.Parent;
    while (p != null) { if (p is Project pr) { Console.WriteLine($"  Csc in: {pr.Name} ({pr.ProjectFile})"); break; } p = p.Parent; }
}

// Check for MSB errors (project dependency failures)
var allMessages = build.FindChildrenRecursive<Message>().Where(m => m.Text != null && m.Text.Contains("MSB")).Take(10).ToList();
Console.WriteLine($"\nMSB messages: {allMessages.Count}");
foreach (var m in allMessages)
    Console.WriteLine($"  {m.Text?.Substring(0, Math.Min(200, m.Text.Length))}");
EOF
